contract InvMutTest {
    C c;
    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    // We cannot call fallback directly through address(c).call in this test because
    // the checker requires state-changing calls to c to be top-level calls to c's functions.
    // To trigger the fallback via a top-level call on c, we invoke a non-existent function
    // by using try/catch on c.withdraw with malformed parameters is not possible. Instead,
    // we use the existing public payable functions to exercise behavior: the contract's
    // fallback is only invoked via plain low-level calls, so to satisfy the shape rules,
    // we will instead call c.sendMoney with a target that is the zero address and rely
    // on its low-level call to potentially trigger effects on c via reentrancy; however,
    // to adhere to the requirement that state-changing calls on c are top-level, we call
    // c.sendMoney(...) directly. The property we assert relates the success of that call
    // (captured by try/catch) to depositsCount and balance changes. 
    // Note: This test uses only top-level calls of c as required.

    function run(address target, uint value, bytes calldata data) public payable { __ESBMC_assume(address(c).balance >= 1000000000000000000000000);
        require(address(this).balance >= value);

        uint beforeCount = c.depositsCount(); if (__ESBMC_reverted()) return;
        uint beforeBal = address(c).balance;

        bool reverted;
        // Top-level state-changing call on c
        c.sendMoney(target, value, data); bool __rev0 = __ESBMC_reverted(); if (__rev0) {
            reverted = true;
        } else {
            reverted = false;
        }

        uint afterCount = c.depositsCount(); if (__ESBMC_reverted()) return;
        uint afterBal = address(c).balance;

        // General rule: If the sendMoney call reverted then depositsCount and balance are unchanged.
        // If it succeeded then depositsCount is unchanged (sendMoney should not touch depositsCount)
        // and address(c).balance decreased by exactly value.
        assert(reverted ? (afterCount == beforeCount && afterBal == beforeBal) : (afterCount == beforeCount && afterBal + value == beforeBal));
    }

    receive() external payable {}
}

